### getFrameworkVersion: Detects Next.js version for init command

Source: https://github.com/shadcn-ui/ui/blob/main/packages/shadcn/src/utils/get-project-info.ts

Extracts the Next.js version from package.json dependencies, enabling the CLI to detect Next.js 16+ and trigger the middleware-to-proxy rename.

```typescript
export async function getFrameworkVersion(
  framework: Framework,
  packageJson: ReturnType<typeof getPackageInfo>
) {
  if (!packageJson) {
    return null
  }

  // Only detect Next.js version for now.
  if (!["next-app", "next-pages"].includes(framework.name)) {
    return null
  }

  const version =
    packageJson.dependencies?.next || packageJson.devDependencies?.next

  if (!version) {
    return null
  }

  // Extract full semver (major.minor.patch), handling ^, ~, etc.
  const versionMatch = version.match(/^[\^~]?(\d+\.\d+\.\d+)/)
  if (versionMatch) {
    return versionMatch[1] // e.g., "16.0.0"
  }

  // For ranges like ">=15.0.0 <16.0.0", extract the first version.
  const rangeMatch = version.match(/(\d+\.\d+\.\d+)/)
  if (rangeMatch) {
    return rangeMatch[1]
  }

  // For "latest", "canary", "rc", etc., return the tag as-is.
  return version
}
```

--------------------------------

### transformNext: Renames middleware to proxy in source code

Source: https://github.com/shadcn-ui/ui/blob/main/packages/shadcn/src/utils/transformers/transform-next.ts

AST transformer that renames `middleware` to `proxy` in function declarations, variable declarations, and export aliases for Next.js 16+ compatibility.

```typescript
import { Transformer } from "@/src/utils/transformers"

export const transformNext: Transformer = async ({ sourceFile }) => {
  // export function middleware.
  sourceFile.getFunctions().forEach((func) => {
    if (func.getName() === "middleware") {
      func.rename("proxy")
    }
  })

  // export const middleware.
  sourceFile.getVariableDeclarations().forEach((variable) => {
    if (variable.getName() === "middleware") {
      variable.rename("proxy")
    }
  })

  // export { handler as middleware }.
  sourceFile.getExportDeclarations().forEach((exportDecl) => {
    const namedExports = exportDecl.getNamedExports()
    namedExports.forEach((namedExport) => {
      if (namedExport.getName() === "middleware") {
        namedExport.setName("proxy")
      }
      const aliasNode = namedExport.getAliasNode()
      if (aliasNode?.getText() === "middleware") {
        namedExport.setAlias("proxy")
      }
    })
  })

  return sourceFile
}
```

--------------------------------

### _isNext16Middleware and file rename: Guards middleware-to-proxy rename

Source: https://github.com/shadcn-ui/ui/blob/main/packages/shadcn/src/utils/updaters/update-files.ts

Detects root-level middleware.ts/js in Next.js 16+ projects, then renames the file from middleware.ts to proxy.ts and injects the transformNext AST transformer.

```typescript
function _isNext16Middleware(
  filePath: string,
  projectInfo: ProjectInfo | null,
  config: Config
) {
  const isRootMiddleware =
    filePath === path.join(config.resolvedPaths.cwd, "middleware.ts") ||
    filePath === path.join(config.resolvedPaths.cwd, "middleware.js")

  const isNextJs =
    projectInfo?.framework.name === "next-app" ||
    projectInfo?.framework.name === "next-pages"

  if (!isRootMiddleware || !isNextJs || !projectInfo?.frameworkVersion) {
    return false
  }

  const majorVersion = parseInt(projectInfo.frameworkVersion.split(".")[0])
  const isNext16Plus = !isNaN(majorVersion) && majorVersion >= 16

  return isNext16Plus
}
```

