### transformNext: Renames middleware to proxy in source code

Source: https://github.com/shadcn-ui/ui/blob/main/packages/shadcn/src/utils/transformers/transform-next.ts

AST transformer that renames `middleware` to `proxy` in function declarations, variable declarations, and export aliases for Next.js 16+ compatibility.

```typescript
import { Transformer } from "@/src/utils/transformers"

export const transformNext: Transformer = async ({ sourceFile }) => {
  // export function middleware.
  sourceFile.getFunctions().forEach((func) => {
    if (func.getName() === "middleware") {
      func.rename("proxy")
    }
  })

  // export const middleware.
  sourceFile.getVariableDeclarations().forEach((variable) => {
    if (variable.getName() === "middleware") {
      variable.rename("proxy")
    }
  })

  // export { handler as middleware }.
  sourceFile.getExportDeclarations().forEach((exportDecl) => {
    const namedExports = exportDecl.getNamedExports()
    namedExports.forEach((namedExport) => {
      if (namedExport.getName() === "middleware") {
        namedExport.setName("proxy")
      }
      const aliasNode = namedExport.getAliasNode()
      if (aliasNode?.getText() === "middleware") {
        namedExport.setAlias("proxy")
      }
    })
  })

  return sourceFile
}
```

