### preFlightAdd: components.json existence check

Source: https://github.com/shadcn-ui/ui/blob/main/packages/shadcn/src/preflights/preflight-add.ts

If components.json exists and is valid, init is not required — the config is returned and used directly. If missing, a MISSING_CONFIG error is set. If invalid, it exits with a message telling the user to run init.

```typescript
  // Check for existing components.json file.
  if (!fs.existsSync(path.resolve(options.cwd, "components.json"))) {
    // Check if we're in a monorepo root.
    if (await isMonorepoRoot(options.cwd)) {
      const targets = await getMonorepoTargets(options.cwd)
      if (targets.length > 0) {
        formatMonorepoMessage("add [component]", targets)
        process.exit(1)
      }
    }

    errors[ERRORS.MISSING_CONFIG] = true
    return {
      errors,
      config: null,
    }
  }

  try {
    const config = await getConfig(options.cwd)

    return {
      errors,
      config: config!,
    }
  } catch (error) {
    logger.break()
    logger.error(
      `An invalid ${highlighter.info(
        "components.json"
      )} file was found at ${highlighter.info(
        options.cwd
      )}.\nBefore you can add components, you must create a valid ${highlighter.info(
        "components.json"
      )} file by running the ${highlighter.info("init")} command.`
    )
    logger.error(
      `Learn more at ${highlighter.info(`${SHADCN_URL}/docs/components-json`)}.`
    )
    logger.break()
    process.exit(1)
  }
